/**
 * pdf-export.ts — 诊断报告 PDF 导出
 *
 * 咨询 Agent 维度缺口: 将 HTML 诊断报告导出为 PDF。
 * 当前实现基于 HTML→PDF 转换（无需外部依赖如 puppeteer）。
 * 生产环境后续可对接 headless Chrome/Playwright 实现像素级渲染。
 */
export type PDFPageSize = 'A4' | 'Letter' | 'Legal';
export type PDFOrientation = 'portrait' | 'landscape';
export interface PDFExportOptions {
    /** 页面尺寸 */
    pageSize?: PDFPageSize;
    /** 页面方向 */
    orientation?: PDFOrientation;
    /** 是否包含封面 */
    includeCover?: boolean;
    /** 是否包含目录 */
    includeTOC?: boolean;
    /** 页眉文字 */
    headerText?: string;
    /** 页脚文字 */
    footerText?: string;
    /** 报告标题（用于封面） */
    title?: string;
    /** 报告日期 */
    date?: string;
    /** 生成组织 */
    organization?: string;
}
export interface PDFExportResult {
    /** Base64 编码的 PDF 内容 */
    base64: string;
    /** 文件大小（字节） */
    sizeBytes: number;
    /** 页数（估算） */
    estimatedPages: number;
    /** 生成时间 */
    generatedAt: string;
    /** 报告标题 */
    title: string;
}
/**
 * 将 HTML 报告包装为可打印的 PDF-ready HTML。
 * 添加 @page CSS 规则、封面页、页眉页脚。
 */
export declare function wrapHTMLForPDF(htmlBody: string, options?: PDFExportOptions): string;
/**
 * 将 HTML 报告导出为 PDF-ready HTML（可被浏览器 print 或 headless Chrome 消费）。
 *
 * 当前策略：生成 PDF-ready HTML → 浏览器打印 / headless Chrome 渲染。
 * 纯内存操作，零外部依赖。
 *
 * @param htmlBody 诊断报告的 HTML body（不含 <html>/<head>/<body> 标签）
 * @param options 导出选项
 * @returns PDFExportResult
 */
export declare function exportToPDF(htmlBody: string, options?: PDFExportOptions): PDFExportResult;
/**
 * 精简版导出——仅含核心发现（1-2 页）。
 * 用于 IM 推送附件或快速预览。
 */
export declare function exportSummaryToPDF(summary: string, title: string, options?: PDFExportOptions): PDFExportResult;
